INSERT INTO public.properties (id, slug, title, title_en, description, description_en, price, currency, type, status, location, area, rooms, bathrooms, floor, year_built, heating, parking, balcony, storage, cover_image, gallery, featured, published, created_at) VALUES
('p1', 'penthouse-copou-panorama', 'Penthouse cu panoramă — Copou', 'Penthouse with panorama — Copou', 'Un penthouse rar, cu deschidere generoasă spre Iași. Finisaje italiene, tavane înalte de 3,2 m, terasă privată de 42 m² și lift direct în apartament. Locație discretă, la câțiva pași de Grădina Botanică.', 'A rare penthouse with generous views over Iași. Italian finishes, 3.2 m ceilings, 42 m² private terrace and direct lift access. Discreet location, steps from the Botanical Garden.', 385000, 'EUR', 'penthouse', 'nou', 'Copou, Iași', 168, 4, 2, '7/7', 2023, 'Centrală proprie', true, true, true, 'https://images.unsplash.com/photo-1613490493576-7fde63acd811?w=1600&q=80', ARRAY['https://images.unsplash.com/photo-1642976975710-1d8890dbf5ab?w=1600&q=80','https://images.unsplash.com/photo-1628745277862-bc0b2d68c50c?w=1600&q=80','https://images.unsplash.com/photo-1560185893-a55cbc8c57e8?w=1600&q=80','https://images.unsplash.com/photo-1507652313519-d4e9174996dd?w=1600&q=80','https://images.unsplash.com/photo-1493246318656-5bfd4cfb29b8?w=1600&q=80','https://images.unsplash.com/photo-1616594039964-ae9021a400a0?w=1600&q=80'], true, true, '2024-11-15'),
('p2', 'vila-bucium-arhitectura', 'Vilă contemporană — Bucium', 'Contemporary villa — Bucium', 'Vilă de autor pe un teren de 720 m², cu piscină încălzită și grădină matură. Volume curate, lumină abundentă, materiale nobile: piatră naturală, stejar masiv și oțel patinat.', 'A signature villa on 720 m² of land with heated pool and mature garden. Clean volumes, abundant light, noble materials.', 720000, 'EUR', 'vila', 'nou', 'Bucium, Iași', 340, 6, 3, 'P+1', 2022, 'Pompă de căldură', true, true, true, 'https://images.pexels.com/photos/1488267/pexels-photo-1488267.png?w=1600', ARRAY['https://images.unsplash.com/photo-1531971589569-0d9370cbe1e5?w=1600&q=80','https://images.unsplash.com/photo-1583847268964-b28dc8f51f92?w=1600&q=80','https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?w=1600&q=80','https://images.pexels.com/photos/18285887/pexels-photo-18285887.jpeg?w=1600','https://images.pexels.com/photos/31525748/pexels-photo-31525748.jpeg?w=1600'], true, true, '2024-10-22'),
('p3', 'apartament-centrul-istoric', 'Apartament în inima centrului istoric', 'Apartment in the historic heart', 'Apartament clasic reinterpretat contemporan, într-o clădire de patrimoniu restaurată. Detalii originale păstrate cu grijă, îmbinate cu confortul modern.', 'A classic apartment reinterpreted contemporarily, in a restored heritage building.', 215000, 'EUR', 'apartament', 'nou', 'Centrul Istoric, Iași', 112, 3, 2, '2/4', 1928, 'Centrală proprie', false, true, false, 'https://images.unsplash.com/photo-1642976975710-1d8890dbf5ab?w=1600&q=80', ARRAY['https://images.unsplash.com/photo-1560185893-a55cbc8c57e8?w=1600&q=80','https://images.unsplash.com/photo-1628745277862-bc0b2d68c50c?w=1600&q=80','https://images.unsplash.com/photo-1507652313519-d4e9174996dd?w=1600&q=80'], true, true, '2024-09-30'),
('p4', 'penthouse-palas-view', 'Penthouse Palas — vedere panoramică', 'Palas Penthouse — panoramic view', 'Duplex spectaculos deasupra ansamblului Palas, cu terasă generoasă orientată spre Palatul Culturii. Living cu tavane duble, dormitor master cu dressing walk-in.', 'Spectacular duplex above the Palas ensemble, with a generous terrace facing the Palace of Culture.', 495000, 'EUR', 'penthouse', 'rezervat', 'Palas, Iași', 195, 5, 3, '11/12', 2021, 'Centralizat', true, true, true, 'https://images.unsplash.com/photo-1493246318656-5bfd4cfb29b8?w=1600&q=80', ARRAY['https://images.unsplash.com/photo-1702411200201-3061d0eea802?w=1600&q=80','https://images.unsplash.com/photo-1616594039964-ae9021a400a0?w=1600&q=80','https://images.unsplash.com/photo-1583847268964-b28dc8f51f92?w=1600&q=80'], true, true, '2024-11-01'),
('p5', 'casa-miroslava-familia', 'Casă familială — Miroslava', 'Family house — Miroslava', 'Casă modernă pe un teren de 500 m², la 10 minute de Iași. Zonă rezidențială liniștită, curte generoasă și acces facil către oraș.', 'Modern house on 500 m² of land, 10 minutes from Iași.', 245000, 'EUR', 'casa', 'nou', 'Miroslava', 210, 4, 2, 'P+M', 2024, 'Pompă de căldură', true, true, true, 'https://images.unsplash.com/photo-1531971589569-0d9370cbe1e5?w=1600&q=80', ARRAY['https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?w=1600&q=80','https://images.pexels.com/photos/1488267/pexels-photo-1488267.png?w=1600'], false, true, '2024-08-14'),
('p6', 'apartament-tudor-vladimirescu', 'Apartament luminos — Tudor Vladimirescu', 'Light-filled apartment — Tudor Vladimirescu', 'Apartament renovat integral într-un ansamblu rezidențial premium. Orientare est-vest, două balcoane și loc de parcare subteran.', 'Fully renovated apartment in a premium residential ensemble.', 128000, 'EUR', 'apartament', 'nou', 'Tudor Vladimirescu, Iași', 78, 3, 1, '4/8', 2019, 'Centrală proprie', true, true, false, 'https://images.unsplash.com/photo-1628745277862-bc0b2d68c50c?w=1600&q=80', ARRAY['https://images.unsplash.com/photo-1560185893-a55cbc8c57e8?w=1600&q=80','https://images.unsplash.com/photo-1507652313519-d4e9174996dd?w=1600&q=80'], false, true, '2024-07-20'),
('p7', 'vila-galata-lac', 'Vilă cu vedere la lac — Galata', 'Lakeside villa — Galata', 'Rezidență privată pe un teren de 1.100 m², cu deschidere spectaculoasă spre lacul Ciric. Arhitectură contemporană, integrată cu peisajul natural.', 'Private residence on 1,100 m² of land, with a spectacular opening towards Ciric lake.', 890000, 'EUR', 'vila', 'nou', 'Galata, Iași', 420, 7, 4, 'S+P+1', 2023, 'Pompă de căldură geotermală', true, true, true, 'https://images.unsplash.com/photo-1505693416388-ac5ce068fe85?w=1600&q=80', ARRAY['https://images.unsplash.com/photo-1613490493576-7fde63acd811?w=1600&q=80','https://images.pexels.com/photos/1488267/pexels-photo-1488267.png?w=1600','https://images.unsplash.com/photo-1583847268964-b28dc8f51f92?w=1600&q=80'], true, true, '2024-11-28'),
('p8', 'garsoniera-independentei', 'Studio designer — Bd. Independenței', 'Designer studio — Independenței Blvd.', 'Studio compact și rafinat, gândit de un arhitect ieșean. Ideal pentru investiție sau locuință pied-à-terre.', 'Compact and refined studio, designed by an Iași architect.', 79000, 'EUR', 'apartament', 'nou', 'Independenței, Iași', 42, 1, 1, '3/10', 2020, 'Centrală proprie', false, true, false, 'https://images.unsplash.com/photo-1560185893-a55cbc8c57e8?w=1600&q=80', ARRAY['https://images.unsplash.com/photo-1702411200201-3061d0eea802?w=1600&q=80'], false, true, '2024-06-10')
